            "showing_the_first_of_export_the_csv": "Se muestran los primeros {{VIEW_CAP}} de {{total}}: exporta el CSV para ver la lista completa.",
            "full_transfer_ledger_for_the_period_received": "Libro completo de transferencias del periodo. Las transferencias recibidas son adquisiciones (fijan el coste de adquisición); solo los envíos a terceros y los swaps son enajenaciones imponibles, que aparecen más abajo en Enajenaciones.",
            "opening_received_disposed_closing_per_token_open": "Inicial + recibido − enajenado = final, por token. El saldo inicial refleja los importes que hayas definido en Avanzado.",
            "total_gain_taxable": "Ganancia total {{fmtFiat}} {{fiat}} · imponible {{fmtFiat_2}} {{fiat_2}} {{fmtFiat_3}} {{fmtFiat_4}} {{fmtFiat_5}}",
            "not_taxable_disposals_or_income_proposal_fees": "No son enajenaciones imponibles ni ingresos. Las comisiones de propuestas salen de la cuenta y reducen tus tenencias; los retiros de ahorros completados y los power up son movimientos internos, mostrados por integridad.",
            "seen_in_history_but_not_booked_into": "Aparecen en el historial pero no se contabilizan en las cifras anteriores ({{skippedTotal}} operaciones): acciones sociales o de gobernanza sin efecto en el saldo, ingresos ya contados al reclamarlos, o movimientos liquidados en una ejecución posterior:",
            "reconstructed_from_classified_events": "Reconstruido a partir de {{ingest}} eventos clasificados.{{text}}{{fiat}}{{text_2}}{{note}}",
            "deductions_optional_losses_you_carried_forward_f": "Deducciones — opcional. Las pérdidas trasladadas de años anteriores compensan las ganancias de este año; la cifra de exención anual indica cuánto del límite de tu país ya has usado en otro sitio. Se aplican automáticamente cuando tu jurisdicción las contempla.",
            "send_labels_are_assigned_in_the_classify": "Las etiquetas de envío se asignan en el paso Clasificar y se recuerdan por cuenta. Si lo prefieres, edítalas en bloque en una hoja de cálculo:",
            "say_what_each_outbound_send_was_so": "Indica qué fue cada envío saliente para que tribute correctamente. Todo envío se trata como una venta imponible salvo que lo etiquetes: marcarlo como tu propio exchange, tus propias carteras, un regalo o una donación cambia la tributación. Las etiquetas se recuerdan la próxima vez. Continuar las aplica y recalcula el informe.",
            "nothing_to_classify_no_outbound_transfers_to": "Nada que clasificar: no se encontraron transferencias salientes a terceros en tu historial. Continúa para revisar y exportar.",
            "opening_balances_are_tokens_you_already_held": "Los saldos iniciales son tokens que ya tenías antes de la primera operación registrada de esta cuenta. Defínelos para que las enajenaciones antiguas tengan un coste real en lugar de una ganancia con coste cero (sobrevalorada). El coste es el total que pagaste por ese importe inicial, en {{cur}}.",
            "generate_a_record_of_your_on_chain": "Genera un registro de tu actividad en cadena en un intervalo de fechas, clasificado a efectos fiscales por el motor FairFlow. Rellena las opciones, clasifica tus envíos y exporta en PDF, CSV o JSON.",
            "values_use_the_wallets_current_price_a": "Los valores usan el precio actual en {{fiat}} de la cartera: una única instantánea en vivo, sin feed histórico. Por eso el total de tenencias es exacto, pero las ganancias realizadas son aproximadas (los ingresos y el coste de una enajenación comparten el mismo precio actual). Conecta un oráculo histórico o una fuente Kursliste para obtener ganancias exactas.",
            "fiat_values_come_from_the_engines_pxs": "Los valores en moneda fiat provienen del proveedor de precios de demostración referenciado a PXS del motor ({{priceDataVersion}}): conecta un oráculo real o una fuente Kursliste antes de confiar en las cifras.",
            "prefilled_from_the_chain_1_vest_pxa": "Rellenado desde la cadena: 1 VEST = {{_vestingRateAuto}} PXA, así que 1.000.000 VESTS = {{_vestingRateAuto_2}} PXP. VESTS × este valor = PXP, y 1 PXP equivale en valor a 1 PXA. Edítalo solo para sobrescribirlo.",
