            "pixa_is_one_living_being_and_pxa": "Pixa es un solo ser vivo, y PXA y PXP son su <0>cuerpo</0>: el <1>Atlas</1>, una sustancia en dos fases. El PXP es la <2> fase sólida</2>: PXA solidificado 1:1 para dar al ser <3> peso</3> (gobernanza) y ancho de banda sin comisiones. Es además el lastre que orienta la <4>mente</4>: los witnesses se eligen con PXP en stake, así que la mente es algo que el cuerpo forma sobre sí mismo. Vuélvelo a PXA líquido cuando quieras, mediante una liberación de trece semanas que ninguna parte puede alterar.",
            "pxp_is_pxa_0_frozen_solid_0": "El PXP es PXA <0>solidificado</0>: puesto en stake uno a uno para dar al cuerpo peso y voz. <1>Licúalo</1> y vuelve a ser PXA líquido a lo largo de una liberación de trece semanas. Misma sustancia, dos fases; juntas son el <2>Atlas</2>.",
            "staking_is_not_idle_it_buys_four": "Hacer stake no es estar quieto. Compra cuatro cosas, y una de ellas orienta la mente sin hacer ruido.",
            "unstaking_is_gradual_and_fixed_power_down": "Deshacer el stake es gradual y fijo. Haz power down y tu PXP se licúa en PXA en <0> trece tramos semanales iguales</0>: unos noventa y un días. El ritmo lo fija el protocolo; ninguna parte puede acelerarlo ni frenarlo.",
            "each_week_another_equal_slice_melts_back": "Cada semana otra porción igual se licúa en PXA, así que tu saldo se vuelve disponible en una subida constante y previsible hasta el 100 %. Ilustra el calendario, no son datos en vivo.",
            "pxp_is_a_nutzungs_token_a_utility": "El PXP es un Nutzungs-Token —un token de utilidad— según la lectura de la FINMA del 27 de marzo de 2025 (ref. G01518211).",
            "it_confers_protocol_functionality_governance_and": "Confiere funcionalidad de protocolo —gobernanza y ancho de banda sin comisiones— no un derecho sobre los beneficios o los activos de Pixagram SA. Participar en la gobernanza no es una inversión; hacer stake para ayudar a operar el protocolo no es un esquema de inversión colectiva. Y algo crucial: mantener PXP no paga <0>ningún interés</0>; los retornos vienen solo de la participación activa —publicar, votar, curar— nunca de un rendimiento pasivo. No es un medio de pago ni un depósito: no hay emisor que deba devolver nada, y la LICol no se aplica."
