            "twenty_one_witnesses_elected_by_staked_pxp_each": "Veintiún witnesses, elegidos por el PXP en stake, publican cada uno una lectura: el precio local de un Big Mac, de un café — poder adquisitivo, no una moneda. Como los reporteros son elegidos por la base de colateral, la referencia es un modelo que esa base elabora sobre sí misma.",
