            "a_median_across_the_twenty_one_witnesses_rejects": "Una mediana entre los veintiún witnesses descarta a un reportero corrupto; una mediana sobre una ventana de 84 horas — tres días y medio, muestreados cada hora — descarta un pico momentáneo. Caro de corromper, lento de manipular: robusto por construcción, no por confianza. Ningún banco central, ninguna cesta del FMI, ningún feed del BPI.",
