            "no_one_can_steal_or_recover_your": "NADIE PUEDE ROBAR NI RECUPERAR TU CUENTA SIN TU SEMILLA O TU CONTRASEÑA",
            "keep_them_in_a_safe_place_and": "Guárdalas en un lugar seguro y no las compartas nunca. Nuestro equipo jamás te las pedirá.",
            "private_key_on_clipboard_warning": "Clave privada copiada. El portapapeles puede leerse desde otras aplicaciones y sincronizarse fuera de este dispositivo: pégala ahora, se sobrescribirá en 30 segundos.",
