            "permissions_use_your_key_to": "<b>Permisos de {{title}}</b><br>Usa tu {{title}} para:",
            "effective_in_strong_strong_day": "— efectivo en <strong>%n</strong> {{{_plurals.day}}}",
            "adding_a_password_provides_extra_security_especi": "Añadir una contraseña aporta seguridad adicional, sobre todo con frases semilla cortas.",
            "you_are_about_to_request_a_change": "Estás a punto de solicitar un cambio de cuenta de recuperación para <0>@{{username}}</0>.",
            "nominate_a_trusted_account_a_co_founder": "Designa una cuenta de confianza —una persona cofundadora, una cartera hermana que controles o un contacto al que puedas llegar por otra vía— que te ayude a recuperar el acceso si alguna vez pierdes o se ve comprometida tu clave owner. El proceso de recuperación usa el historial de tu clave owner, así que la cuenta de recuperación por sí sola nunca puede apoderarse de tu cuenta: solo puede ayudarte a recuperarla. Los cambios surten efecto tras un periodo de espera de 30 días.",
            "strong_30_day_waiting_period_strong_changing": "<strong>Periodo de espera de 30 días.</strong> Cambiar la cuenta de recuperación no es inmediato. Una nueva solicitud es efectiva <strong>30 días después de transmitirla</strong>; hasta entonces sigue vigente la cuenta actual. Volver a transmitir durante la espera sustituye la solicitud pendiente. Volver a fijar el valor actual cancela un cambio pendiente.",
            "pick_someone_you_trust_personally_a_co": "Elige a alguien en quien confíes personalmente: una persona cofundadora, una cuenta hermana que controles o una cartera cuyo dueño puedas contactar por otra vía.",
            "generate_a_fresh_seed_phrase_to_derive": "Genera una nueva frase semilla para derivar claves nuevas de tu cuenta. Tu frase semilla es la clave maestra de todas las claves de la cuenta: guárdala a salvo y no la compartas nunca. La clave owner se usará para firmar la transacción de actualización cuando confirmes abajo.",
            "this_will_strong_cancel_any_pending_recovery": "Esto <strong>cancelará cualquier cambio pendiente de cuenta de recuperación</strong> al volver a transmitir el mismo valor que la cuenta actual. La solicitud de 30 días será sustituida; la cuenta de recuperación actual permanece vigente todo el tiempo.",
            "once_broadcast_the_chain_will_create_a": "Una vez transmitida, la cadena creará una solicitud pendiente que será efectiva en <strong>30 días</strong>. Tu cuenta de recuperación actual (<0>@{{currentRecovery}}</0>) seguirá vigente hasta entonces. Se te pedirá tu <strong>clave owner</strong>.",
            "posting_description_1": "Esta clave debe usarse para acciones de red social, como publicar, comentar y votar. Tiene un conjunto limitado de permisos y no puede usarse para acciones monetarias.",
            "posting_description_2": "Usa esta clave para iniciar sesión en redes sociales basadas en Pixa como Pixagram.com. Guárdala en un lugar seguro.",
            "active_description_1": "Esta clave tiene permisos adicionales para acciones monetarias más sensibles, como transferir e intercambiar tokens.",
            "active_description_2": "Al realizar una acción relacionada con la cartera, puede que se te pida autenticarte con tu clave Active. Introduce tu Active Key solo en aplicaciones de confianza, porque cualquiera con acceso a esta clave puede llevarse tus tokens.",
            "owner_description_1": "La clave Owner es necesaria para cambiar las demás claves. Tiene permisos adicionales para recuperar tu cuenta o cambiar tus otras claves. Es la clave más importante y debe guardarse de forma segura sin conexión.",
            "memo_description_1": "La clave Memo es un caso aparte. Lo único que puede hacer la Memo Key es cifrar y descifrar mensajes privados enviados a través de la blockchain.",
