            "at_genesis_the_chain_minted_a_fixed": "En la génesis, la cadena acuñó una asignación fija en tres cuentas de tesorería. Esta pestaña sigue lo que ha salido de ellas desde entonces, a partir del registro de tokenomics.json, y lee los saldos en vivo para cotejarlos con él.",
            "minted_pxa": "PXA acuñados",
