            "what_the_tge_minted": "Qué acuñó el TGE",
            "at_genesis_the_pixa_chain_minted_pxa": "En la génesis, la cadena Pixa acuñó {{pixa}} PXA y {{pxs}} PXS en tres cuentas de tesorería: {{teamAmount}} PXA para {{team}}, {{companyAmount}} PXA para {{company}} y {{dpfAmount}} PXS para {{dpf}}. Estos tres saldos son la asignación del TGE; todo lo que han pagado desde entonces se lista abajo, cuenta por cuenta.",
            "two_special_accounts": "Dos cuentas especiales",
            "and_are_multi_signature_accounts_restricted_at": "{{team}} y {{company}} son cuentas multifirma restringidas a nivel de protocolo: solo pueden transferir Pixa Power (PXP), el token de utilidad en stake, y no pueden mover PXA ni PXS líquidos. Nunca votan — ni por witnesses ni sobre propuestas — así que su stake no tiene peso alguno en la gobernanza.",
            "two_policies": "Dos políticas",
            "is_discretionary_the_team_rewards_contributors": "{{team}} es discrecional: el equipo recompensa a los contribuidores en PXP como considere oportuno, sin calendario ni tope. {{company}} sigue una hoja de ruta fija: toda su asignación debe distribuirse entre {{min}} y {{max}} años después del TGE — ni más, ni menos. Tanto las ventas directas como las transferencias a la cuenta operativa, que hace power down del PXP a PXA líquido para los exchanges, cuentan como distribución.",
            "the_decentralized_pixa_fund": "El Decentralized Pixa Fund",
            "is_the_decentralized_pixa_fund_it_has": "{{dpf}} es el Decentralized Pixa Fund. No tiene claves privadas, así que nadie puede firmar por él: sus PXS solo salen mediante propuestas aprobadas por el voto de los participantes, como máximo 1/{{divider}} del saldo al día, y el fondo sigue recibiendo su parte de la inflación de la cadena.",
