            "the_team_may_use_these_funds_at": "El equipo puede usar estos fondos a su discreción — para recompensar a los contribuidores en Pixa Power — sin calendario ni regla de importe. Los únicos límites son los de la propia cuenta: solo transferencias de PXP y ningún voto.",
            "the_company_treasury_must_be_fully_distributed": "La tesorería de la empresa debe distribuirse por completo entre {{min}} y {{max}} años después del TGE — ni más, ni menos. Esta es la hoja de ruta de la distribución.",
            "the_dpf_has_no_private_keys_its": "El DPF no tiene claves privadas. Sus PXS solo pueden salir mediante propuestas aprobadas por el voto de los participantes, como máximo 1/{{divider}} del saldo al día.",
