            "strong_steem_strong_launched_in_2016_as": "<strong>STEEM</strong> se lanzó en 2016 como la primera cadena social: una cadena donde publicar, votar y comentar son las transacciones. En 2018 se valoraba en más de{{text}}<strong>mil millones de dólares</strong> y llegó a estar entre las <strong>10 principales criptomonedas</strong>.",
