            "to_create_and_to_curate_is_worth": " Crear y curar vale más que guardar en silencio; quienes se presentan son la sustancia viva de Pixa, y para ellos se construye primero.",
            "and_most_beautiful_of_all_are_the": " — y más bellas que todas son las manos que las hacen. Honra al creador en la obra.",
