            "these_principles_are_the_foundation_of_pixa": "Estos principios son los cimientos de Pixa y de la comunidad que construimos sobre ella: honesta, justa, duradera y unida. El protocolo prohíbe solo lo que debe; todo lo bueno más allá de esa línea es el carácter que elegimos. Este es ese carácter: el espíritu con el que creamos, la forma en que nos tratamos unos a otros y la vara con la que nos medimos. No obligan a nadie por la fuerza y, aun así, nos obligan a todos.",
