            "permission_is_granted_without_charge_to_any": "Por la presente se concede permiso, de forma gratuita, a cualquier entidad que obtenga una copia de este software y de los archivos de documentación asociados (el «Software») para disponer del Software sin restricción alguna. Ello incluye los derechos de usar, copiar, modificar, fusionar, publicar, distribuir, sublicenciar y/o vender copias del Software, así como de permitir hacerlo a las personas a quienes se proporcione el Software, con sujeción a las siguientes condiciones: el aviso de copyright anterior y este aviso de permiso deberán incluirse en todas las copias o partes sustanciales del Software."
