            "no_naimap_set_nai_asset_objects_are_skipped": "No se ha definido naiMap — se omiten los objetos de activo {amount,precision,nai} (API distintas de condenser). Usa condenser_api/get_account_history (cadenas heredadas) o añade naiMap.",
            "recurrent_transfer_set_up_ops": "Las operaciones de configuración de recurrent_transfer (×{{count}}) no conllevan por sí solas ningún movimiento de fondos — cada pago programado se contabiliza en su ejecución fill_recurrent_transfer, por lo que los totales no se cuentan dos veces.",
