            "this_license_provides_a_flexible_transparent": "Esta licencia ofrece un marco de licencias flexible, transparente y justo que puede adaptarse a distintos casos de uso, modelos de negocio e intenciones artísticas, garantizando al mismo tiempo que los derechos morales del Autor permanezcan intactos y plenamente preservados.",
            "this_license_delegates_and_allocates_copyright": "Esta licencia delega y asigna los permisos de derechos de autor, que por defecto son muy estrictos, del Autor al Propietario o Propietarios del NFT y al Visitante o Visitantes. El Autor conserva la plena titularidad de la propiedad intelectual y concede derechos de uso específicos según sus preferencias.",
            "author": "Autor",
