            "anyone_who_views_or_interacts_with_the": "Cualquier persona que vea la obra o interactúe con ella sin ser propietaria del NFT asociado.",
            "legal_agreement": "Acuerdo legal",
            "this_nft_license_agreement_the_agreement": "El presente Acuerdo de Licencia NFT (el «Acuerdo») establece las condiciones personalizables en virtud de las cuales el creador (en lo sucesivo, el «Autor») concede determinados derechos al comprador (el «Poseedor») de tokens no fungibles (NFT) asociados a una colección específica de obras digitales (la «Colección»). El objetivo de este Acuerdo es ofrecer un marco de licencias flexible, transparente y justo que pueda adaptarse a distintos casos de uso, modelos de negocio e intenciones artísticas, garantizando al mismo tiempo que los derechos morales del Autor permanezcan intactos y plenamente preservados. Esta estructura está especialmente diseñada para los creadores de NFT que deseen ofrecer derechos de uso a medida a los poseedores de sus activos digitales, permitiendo diversas interacciones y formas de explotación de la obra en función de las preferencias seleccionadas por el Autor.",
            "ownership_and_moral_rights": "Titularidad y derechos morales",
            "the_author_is_and_shall_remain_the_sole": "El Autor es y seguirá siendo el titular único y exclusivo de todos los derechos de propiedad intelectual sobre las obras subyacentes y sobre cualquier contenido asociado vinculado a los NFT. El Autor conserva todos los derechos morales, incluido el derecho a ser reconocido como creador y a oponerse a cualquier deformación, mutilación u otra modificación de la obra que perjudique su honor o reputación. Estos derechos morales son intransferibles y perpetuos, y deberán ser respetados por todos los Poseedores y terceros. El presente Acuerdo no se interpretará como una renuncia a dichos derechos ni como una limitación de los mismos.",
            "license_options_for_the_holder": "Opciones de licencia para el Poseedor",
            "the_holder_of_an_nft_is_granted_a_non": "Se concede al Poseedor de un NFT una licencia no exclusiva, mundial y libre de regalías para usar la obra digital asociada al NFT, pero solo en la medida en que el Autor lo permita expresamente a continuación. La licencia está vinculada estrictamente al NFT concreto que se posee y se transmite automáticamente en caso de reventa. La finalidad de esta sección es permitir al Autor seleccionar el alcance de los derechos concedidos a cada Poseedor, ofreciendo así claridad jurídica y flexibilidad creativa a ambas partes. Para cada derecho enumerado, el Autor puede indicar si el Poseedor está autorizado a ejercerlo.",
            "rights_granted_to_the_holder": "Derechos concedidos al Poseedor",
